library(creditratingsystem)
if(!exists('.cr_hash',mode='function')) .cr_hash<-getFromNamespace('.cr_hash','creditratingsystem')
pfs_near<-function(a,b,tol=1e-10)stopifnot(length(a)==length(b),all(abs(a-b)<=tol))
pfs_error<-function(expr,code){e<-tryCatch(force(expr),error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
pfs_fixture<-function(shared=FALSE){
 graph<-build_entity_graph(list(list(entity_id='a'),list(entity_id='b')),list(),list(policy_id='g',version='1',edge_types=list('CROSS_DEFAULT')),as_of='2024-01-01',known_at='2024-01-01')
 policy<-list(policy_id='d',version='1',edge_types=list('CROSS_DEFAULT'),direction_policy='mutual_only',transitive=TRUE)
 rows<-lapply(c('a','b'),function(x)list(position_id=paste0('p',x),claim_id=paste0('c',x),facility_id=paste0('f',x),entity_id=if(shared)'a'else x,currency='EUR',ead=100,facility_ead=100,sector='s',region='r',exposure_basis='GROSS',collateral_treatment='NONE'))
 contract<-list(portfolio_id='p',version='1',currency='EUR',as_of='2024-01-01',known_at='2024-01-01',horizon=1,time_unit='years',probability_measure='PHYSICAL',conditioning='initially_performing',event='first_default')
 portfolio<-prepare_credit_portfolio(rows,graph,policy,contract);groups<-portfolio$value$default_group_ids;dependence<-list(kind='SUPPLIED_DEPENDENT_UNIFORMS',group_ids=groups)
 u<-if(shared)list(list(.25),list(.25),list(.75),list(.75))else list(list(.25,.25),list(.25,.75),list(.75,.25),list(.75,.75))
 draws<-list(scenario_ids=list('s1','s2','s3','s4'),weights=rep(list(.25),4),group_ids=groups,sampling_design='EXACT_STATES',group_uniforms=u)
 paths<-list(scenario_ids=draws$scenario_ids,position_ids=list('pa','pb'),driver_hash=.cr_hash(list(dependence_contract=dependence,shared_innovations=draws)),ead=rep(list(list(100,100)),4),lgd=rep(list(list(.5,.5)),4),guarantee_treatment='NOT_YET_APPLIED')
 list(prepared_portfolio=portfolio,group_pds=stats::setNames(rep(list(.5),length(groups)),unlist(groups)),dependence_contract=dependence,shared_innovations=draws,conditional_loss_paths=paths)
}
pfs_args<-pfs_fixture();pfs_independent<-do.call(simulate_credit_portfolio,c(pfs_args,list(levels=.75)))$value;pfs_near(sort(unlist(pfs_independent$portfolio_loss_paths)),c(0,50,50,100));pfs_near(pfs_independent$distribution$expected_loss,50);pfs_near(pfs_independent$distribution$tails[[1]]$value_at_risk,50);pfs_near(pfs_independent$distribution$tails[[1]]$expected_shortfall,100)
pfs_shared<-do.call(simulate_credit_portfolio,c(pfs_fixture(TRUE),list(levels=.75)))$value;pfs_near(unlist(pfs_shared$portfolio_loss_paths),c(100,100,0,0));stopifnot(all(vapply(pfs_shared$position_defaults,function(row)identical(row[[1]],row[[2]]),logical(1))))
pfs_gaussian_args<-pfs_fixture();pfs_gaussian_args$dependence_contract<-list(kind='GAUSSIAN_FACTORS',group_ids=pfs_gaussian_args$prepared_portfolio$value$default_group_ids,factor_ids=list('common'),factor_correlation=list(list(1)),loadings=list(list(1),list(1)))
pfs_gaussian_args$shared_innovations$group_uniforms<-NULL;pfs_gaussian_args$shared_innovations$factor_normals<-list(list(-1),list(-1),list(1),list(1));pfs_gaussian_args$shared_innovations$group_normals<-rep(list(list(0,0)),4);pfs_gaussian_args$conditional_loss_paths$driver_hash<-.cr_hash(list(dependence_contract=pfs_gaussian_args$dependence_contract,shared_innovations=pfs_gaussian_args$shared_innovations))
pfs_gaussian<-do.call(simulate_credit_portfolio,pfs_gaussian_args)$value;pfs_near(unlist(pfs_gaussian$portfolio_loss_paths),c(100,100,0,0));pfs_near(unlist(pfs_gaussian$systematic_asset_variance),c(1,1));pfs_bad<-pfs_gaussian_args;pfs_bad$dependence_contract$loadings<-list(list(1.1),list(1));pfs_error(do.call(simulate_credit_portfolio,pfs_bad),'PORTFOLIO_VARIANCE')
pfs_bad<-pfs_fixture();pfs_bad$conditional_loss_paths$driver_hash<-'wrong';pfs_error(do.call(simulate_credit_portfolio,pfs_bad),'PORTFOLIO_PATHS');pfs_bad<-pfs_fixture();pfs_bad$prepared_portfolio$value$positions[[1]]$ead<-200;pfs_error(do.call(simulate_credit_portfolio,pfs_bad),'LINK_INTEGRITY')
pfs_graph<-build_entity_graph(list(list(entity_id='a'),list(entity_id='b')),list(),list(policy_id='g',version='1',edge_types=list('CROSS_DEFAULT')),as_of='2024-01-01',known_at='2024-01-01');pfs_policy<-list(policy_id='d',version='1',edge_types=list('CROSS_DEFAULT'),direction_policy='mutual_only',transitive=TRUE)
pfs_claims<-list(list(claim_id='ca',entity_id='a',amount=100,currency='EUR',due_at='2025-01-01',known_at='2024-01-01'));pfs_guarantee<-list(guarantee_id='guarantee',guarantor_id='b',currency='EUR',cap=80,cap_used=0,coverage_fraction=1,covered_claim_ids=list('ca'),valid_from='2024-01-01',valid_until='2025-01-02',known_at='2024-01-01',legally_effective=TRUE,evidence_reference='contract')
pfs_allocation<-allocate_guarantee_coverage(list(pfs_guarantee),pfs_claims,list(policy_id='alloc',version='1',guarantee_priority=list('guarantee'),claim_priority=list('ca'),cap_convention='non_reinstating_total'),as_of='2024-01-01',known_at='2024-01-01',currency='EUR')
pfs_guaranteed_args<-pfs_fixture();pfs_old<-pfs_guaranteed_args$prepared_portfolio$value;pfs_contract<-pfs_old$contract;pfs_contract$guarantee_loss_rule<-'FIRST_LOSS_CAP_IF_GUARANTOR_SURVIVES_HORIZON';pfs_guaranteed_args$prepared_portfolio<-prepare_credit_portfolio(pfs_old$positions,pfs_graph,pfs_policy,pfs_contract,guarantee_allocations=list(pfs_allocation));pfs_first_loss<-do.call(simulate_credit_portfolio,pfs_guaranteed_args)$value;pfs_near(sort(unlist(pfs_first_loss$guarantee_payments[[1]]$payments)),c(0,0,0,50));pfs_near(pfs_first_loss$distribution$expected_loss,37.5)
pfs_contract$guarantee_loss_rule<-'PRO_RATA_EAD_CAPPED_IF_GUARANTOR_SURVIVES_HORIZON';pfs_guaranteed_args$prepared_portfolio<-prepare_credit_portfolio(pfs_old$positions,pfs_graph,pfs_policy,pfs_contract,guarantee_allocations=list(pfs_allocation));pfs_prorata<-do.call(simulate_credit_portfolio,pfs_guaranteed_args)$value;pfs_near(sort(unlist(pfs_prorata$guarantee_payments[[1]]$payments)),c(0,0,0,40));pfs_near(pfs_prorata$distribution$expected_loss,40);pfs_error(prepare_credit_portfolio(pfs_old$positions,pfs_graph,pfs_policy,pfs_contract,guarantee_allocations=list(pfs_allocation,pfs_allocation)),'PORTFOLIO_GUARANTEE')
pfs_stress_args<-pfs_gaussian_args;pfs_stress_args$dependence_contract$loadings<-list(list(0),list(0));pfs_stress_args$shared_innovations$group_normals<-list(list(-1,-1),list(-1,1),list(1,-1),list(1,1));pfs_stress_args$conditional_loss_paths$driver_hash<-.cr_hash(list(dependence_contract=pfs_stress_args$dependence_contract,shared_innovations=pfs_stress_args$shared_innovations));pfs_stress_dep<-pfs_stress_args$dependence_contract;pfs_stress_dep$loadings<-list(list(1),list(1));pfs_stress_paths<-pfs_stress_args$conditional_loss_paths;pfs_stress_paths$driver_hash<-.cr_hash(list(dependence_contract=pfs_stress_dep,shared_innovations=pfs_stress_args$shared_innovations));pfs_case<-list(case_id='common',dependence_contract=pfs_stress_dep,group_pds=pfs_stress_args$group_pds,conditional_loss_paths=pfs_stress_paths,recovery_response='FIXED_PATHS');pfs_stress<-do.call(stress_portfolio_factor_structure,c(pfs_stress_args,list(stress_cases=list(pfs_case),levels=.5)))$value;pfs_near(pfs_stress$base$distribution$expected_loss,50);pfs_near(pfs_stress$stress_cases[[1]]$stressed$distribution$expected_loss,50);pfs_near(pfs_stress$base$distribution$tails[[1]]$expected_shortfall,75);pfs_near(pfs_stress$stress_cases[[1]]$stressed$distribution$tails[[1]]$expected_shortfall,100)
pfs_mcontract<-list(contract_id='m',version='1',group_ids=list('g'),states=list('P','D'),default_state='D',allow_cure=FALSE,probability_measure='PHYSICAL',time_grid=list(1,2),time_unit='years',matrix_mode='HOMOGENEOUS',innovation_law='CONDITIONALLY_UNIFORM_GIVEN_PRIOR_STATES');pfs_uniforms<-list();for(a in c(.1,.3,.5,.7,.9))for(b in c(.1,.3,.5,.7,.9))pfs_uniforms[[length(pfs_uniforms)+1L]]<-list(list(a),list(b));pfs_mdraws<-list(scenario_ids=as.list(as.character(0:24)),group_ids=list('g'),values=pfs_uniforms,weights=rep(list(1),25))
pfs_migration<-simulate_portfolio_migrations(list(g='P'),list(list(.8,.2),list(0,1)),pfs_mdraws,pfs_mcontract)$value;pfs_near(pfs_migration$terminal_empirical[[1]]$probabilities$D,.36);pfs_near(pfs_migration$terminal_markov_probabilities[[1]]$probabilities$D,.36);stopifnot(sum(vapply(pfs_migration$grade_paths,function(p)p[[3]][[1]]=='D',logical(1)))==9,sum(vapply(pfs_migration$first_default_times,function(v)identical(v[[1]],1),logical(1)))==5,sum(vapply(pfs_migration$first_default_times,function(v)identical(v[[1]],2),logical(1)))==4)
pfs_identity<-simulate_portfolio_migrations(list(g='P'),list(list(1,0),list(0,1)),pfs_mdraws,pfs_mcontract)$value;stopifnot(all(vapply(pfs_identity$grade_paths,function(v)all(unlist(v)=='P'),logical(1))));pfs_error(simulate_portfolio_migrations(list(g='D'),list(list(1,0),list(1,0)),pfs_mdraws,pfs_mcontract),'PORTFOLIO_MIGRATION');pfs_cure_contract<-pfs_mcontract;pfs_cure_contract$allow_cure<-TRUE;pfs_cure<-simulate_portfolio_migrations(list(g='D'),list(list(1,0),list(1,0)),pfs_mdraws,pfs_cure_contract)$value;stopifnot(all(vapply(pfs_cure$grade_paths,function(v)identical(unlist(v),c('D','P','P')),logical(1))),all(unlist(pfs_cure$first_default_times)==0))
pfs_valuation<-list(valuation_id='v',version='1',currency='EUR',valuation_basis='SUPPLIED_FROZEN_MARKED_VALUES',group_ids=list('g'),states=list('P','D'),initial_values=list(100),terminal_values_by_grade=list(list(98,40)),cash_distributions=rep(list(list(5)),25));pfs_valued<-simulate_portfolio_migrations(list(g='P'),list(list(.8,.2),list(0,1)),pfs_mdraws,pfs_mcontract,valuation_contract=pfs_valuation)$value;stopifnot(pfs_valued$contract$probability_measure=='PHYSICAL');pfs_near(sort(unique(unlist(pfs_valued$marked_values$portfolio_marked_loss_paths))),c(-3,55));pfs_near(mean(unlist(pfs_valued$marked_values$portfolio_marked_loss_paths)),17.88)
if(nzchar(Sys.getenv('CREDITRATING_PORTFOLIO_REPORT')))writeLines(jsonlite::toJSON(list(prepared=pfs_args$prepared_portfolio$value,independent=pfs_independent,shared=pfs_shared,gaussian=pfs_gaussian,guarantee_first_loss=pfs_first_loss,guarantee_prorata=pfs_prorata,stress=pfs_stress,migration=pfs_migration,identity=pfs_identity,cure=pfs_cure,valued=pfs_valued),auto_unbox=TRUE,digits=17,null='null'),Sys.getenv('CREDITRATING_PORTFOLIO_REPORT'))
# Exposure-lot conservation and netting evidence do not create automatic offsets.
pfs_lots<-pfs_old$positions;pfs_lots[[1]]$ead<-40;pfs_extra<-pfs_lots[[1]];pfs_extra$position_id<-'pa2';pfs_extra$claim_id<-'ca2';pfs_extra$ead<-60;pfs_lots[[3]]<-pfs_extra;pfs_lot_prepared<-prepare_credit_portfolio(pfs_lots,pfs_graph,pfs_policy,pfs_old$contract);pfs_near(pfs_lot_prepared$value$total_ead,200);stopifnot(pfs_lot_prepared$diagnostics$position_count==3,pfs_lot_prepared$diagnostics$facility_count==2)
pfs_lots[[3]]$ead<-61;pfs_error(prepare_credit_portfolio(pfs_lots,pfs_graph,pfs_policy,pfs_old$contract),'PORTFOLIO_ALLOCATION')
pfs_netted<-pfs_old$positions;for(i in seq_along(pfs_netted)){pfs_netted[[i]]$exposure_basis<-'NETTED';pfs_netted[[i]]$netting_contract_id<-'n'}
pfs_netting<-list(netting_contract_id='n',facility_ids=list('fa','fb'),currency='EUR',legally_effective=TRUE,evidence_reference='legal_opinion',valid_from='2023-01-01',valid_until='2025-01-01',known_at='2023-01-01');pfs_net_prepared<-prepare_credit_portfolio(pfs_netted,pfs_graph,pfs_policy,pfs_old$contract,netting_contracts=list(pfs_netting));pfs_near(pfs_net_prepared$value$total_ead,200);pfs_error(prepare_credit_portfolio(pfs_netted,pfs_graph,pfs_policy,pfs_old$contract),'PORTFOLIO_NETTING')
pfs_wrong_date<-pfs_contract;pfs_wrong_date$horizon<-2;pfs_error(prepare_credit_portfolio(pfs_old$positions,pfs_graph,pfs_policy,pfs_wrong_date,guarantee_allocations=list(pfs_allocation)),'PORTFOLIO_GUARANTEE')
pfs_tv_contract<-pfs_mcontract;pfs_tv_contract$matrix_mode<-'TIME_VARYING';pfs_tv<-simulate_portfolio_migrations(list(g='P'),list(list(list(.9,.1),list(0,1)),list(list(.7,.3),list(0,1))),pfs_mdraws,pfs_tv_contract)$value;pfs_near(pfs_tv$terminal_markov_probabilities[[1]]$probabilities$D,.37)
